mapper.select:
select oper_id, title, business_type, method, request_method, operator_type, oper_name, dept_name,
	oper_url, oper_ip, oper_location, oper_param, json_result, change_diff, status, error_msg, cost_time, oper_time, user_agent
from sys_oper_log

	AND title like concat('%', #{title}, '%')
	AND business_type = #{businessType}

		AND business_type in
		#{t}

	AND status = #{status}
	AND oper_name like concat('%', #{operName}, '%')
	AND oper_ip like concat('%', #{operIp}, '%')
	AND oper_time >= #{operTimeStart}
	AND oper_time <= #{operTimeEnd}

order by oper_id desc

select oper_id, title, business_type, method, request_method, operator_type, oper_name, dept_name,
	oper_url, oper_ip, oper_location, oper_param, json_result, change_diff, status, error_msg, cost_time, oper_time, user_agent
from sys_oper_log where oper_id = #{operId}
